function validate([inventory, orders]) {
  if (!Array.isArray(inventory) || inventory.length < 1 || inventory.length > 100000) return 'inventory needs 1 to 100000 colors.';
  if (inventory.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each count is an integer from 1 to 10^9.';
  const sum = inventory.reduce((a, b) => a + b, 0);
  if (!Number.isInteger(orders) || orders < 1 || orders > Math.min(sum, 1000000000)) return 'orders is from 1 to min(sum(inventory), 10^9).';
  return null;
}

