function maxProfit(inventory, orders) {
  const MOD = 1000000007n;
  const soldAbove = (k) => {
    let count = 0;
    for (const balls of inventory) {
      if (balls > k) {
        count += balls - k;
      }
    }
    return count;
  };

  let low = 0;
  let high = Math.max(...inventory);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (soldAbove(mid) <= orders) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  const threshold = low;

  let total = 0n;
  let remaining = orders;
  for (const balls of inventory) {
    if (balls > threshold) {
      const top = BigInt(balls);
      const bottom = BigInt(threshold);
      total += (top + bottom + 1n) * (top - bottom) / 2n;
      remaining -= balls - threshold;
    }
  }
  total += BigInt(remaining) * BigInt(threshold);
  return Number(total % MOD);
}

