function maxProfit(inventory, orders) {
  // A different method: sort the counts and lower the tallest colors together, one level band at a time.
  const counts = [...inventory].sort((a, b) => b - a).concat([0]);
  let left = BigInt(orders);
  let total = 0n;
  for (let i = 0; i + 1 < counts.length && left > 0n; i++) {
    const width = BigInt(i + 1);
    const high = BigInt(counts[i]);
    const low = BigInt(counts[i + 1]);
    if (high === low) continue;
    if (width * (high - low) <= left) {
      total += width * ((high + low + 1n) * (high - low) / 2n);
      left -= width * (high - low);
    } else {
      const levels = left / width;
      const extra = left % width;
      total += width * ((2n * high - levels + 1n) * levels / 2n) + extra * (high - levels);
      left = 0n;
    }
  }
  return Number(total % 1000000007n);
}

