function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const n = 1000 + pick(1001);
    const shape = rand();
    const top = shape < 0.3 ? 1000000000 : 1 + pick(1000000000);
    const inventory = Array.from({ length: n }, () => (shape < 0.15 ? top : 1 + pick(top)));
    const sum = inventory.reduce((a, b) => a + b, 0);
    const cap = Math.min(sum, 1000000000);
    const orders = rand() < 0.2 ? cap : 1 + pick(cap);
    return [inventory, orders];
  }
  const n = 1 + pick(5);
  const top = rand() < 0.15 ? 1000000000 : 1 + pick(12);
  const inventory = Array.from({ length: n }, () => (rand() < 0.3 ? top : 1 + pick(top)));
  const sum = inventory.reduce((a, b) => a + b, 0);
  const orders = 1 + pick(Math.min(sum, 60));
  return [inventory, orders];
}
